import { forwardRef, Children, isValidElement, cloneElement, ReactElement } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { AIRatingClasses, StyledAIRating } from "./ai-rating.styles";
import { AIRatingProps } from "./ai-rating.types";

export const AIRating = forwardRef<HTMLDivElement, AIRatingProps>(
  ({ className, children, variant = "default", ...props }, ref) => {
    const theme = useTheme();

    const enforcedChildren = Children.map(children, (child) => {
      if (isValidElement(child)) {
        const type = child.type as { displayName?: string };
        const props = child.props as Record<string, unknown>;
        const newProps: Record<string, unknown> = {};

        if (type?.displayName === "IconButton") {
          if (!props.buttonType) {
            newProps.buttonType = "secondary";
          }
        }

        if (Object.keys(newProps).length > 0) {
          return cloneElement(child as ReactElement, newProps);
        }
      }
      return child;
    });

    return (
      <StyledAIRating
        ref={ref}
        className={clsx(AIRatingClasses.root, className)}
        currentTheme={theme}
        role="group"
        variant={variant}
        {...props}
      >
        {enforcedChildren}
      </StyledAIRating>
    );
  },
);

AIRating.displayName = "AI.Rating";
